use App\Models\Content; use App\Models\Setting; use App\Models\User; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run():void { if(env('ADMIN_EMAIL')&&env('ADMIN_PASSWORD'))User::updateOrCreate(['email'=>env('ADMIN_EMAIL')],['name'=>env('ADMIN_NAME','MyPro Administrator'),'password'=>Hash::make(env('ADMIN_PASSWORD')),'is_admin'=>true]); foreach(['tagline'=>'Making IT Simple','company_name'=>'Myprofessional Solutions, Inc.','brand_name'=>'MyPro Solutions','phone_primary'=>'+632 9177936188','phone_secondary'=>'+632 9992297632','email'=>'sales.myprosolinc@gmail.com','website'=>'www.myprosol.com'] as $k=>$v)Setting::updateOrCreate(['key'=>$k],['value'=>$v,'group'=>'contact']); $this->content(); }
