private function content():void{ $services=[['IT Infrastructure','it-infrastructure','Design and build resilient networks, structured cabling, data centers, connectivity, and power systems.'],['Cybersecurity','cybersecurity','Protect users, systems, networks, and information with layered security and managed monitoring.'],['Computing Devices','computing-devices','Business-ready PCs, laptops, servers, storage, printers, surveillance, power, and accessories.'],['Managed Services','managed-services','Consultative support, helpdesk, administration, preventive maintenance, training, and technical resources.'],['Digital Transformation','digital-transformation','Integrate applications, enterprise HCM, licensing, sustainable energy, and modern digital workflows.']];foreach($services as $s)$this->add('service',$s[0],$s[1],$s[2],'MyPro begins with discovery, maps the technical and business requirements, designs an appropriate solution, coordinates implementation, and provides the knowledge and support needed for adoption.'); foreach([['Large Enterprises','large-enterprises','Scalable infrastructure, security, integration, and support for complex operations.'],['Small & Medium Businesses','small-medium-businesses','Practical technology foundations that grow with the business.'],['Small Office / Home Office','soho','Reliable devices, connectivity, security, and support for focused teams.'],['Retail Market','retail','Devices, connectivity, surveillance, and resilient systems for customer-facing operations.']] as $x)$this->add('industry',...$x); foreach([['Hybrid Security Operations Center','hybrid-security-operations-center','Managed security services in partnership with Sophos and Secureworks.'],['Data Center Design & Build','data-center-design-build','Servers, networks, storage, power, environmental controls, suppression, and physical security.'],['Solar Energy Solutions','solar-energy-solutions','Sustainable solar-energy technology solutions represented in the portfolio.'],['Enterprise Human Capital Management','enterprise-hcm','Enterprise HCM software solutions with ZingHR.']] as $x)$this->add('solution',...$x); foreach([['About Us','about-us','A specialized information technology consultancy and systems integration firm.','Myprofessional Solutions, Inc. has evolved from network and server infrastructure, application deployment, and software and hardware supply into an integrated IT solutions provider serving Philippine organizations.\n\nOur approach is consultative: understand the requirement, design the right-fit solution, coordinate delivery, and support its continued use.'],['Privacy Policy','privacy-policy','How MyPro handles information submitted through this website.','MyPro collects the information you voluntarily provide through inquiry forms to respond to your request. Access is limited to authorized personnel. Contact sales.myprosolinc@gmail.com to request access, correction, or deletion. This policy must be reviewed by legal counsel before production launch.'],['Terms and Conditions','terms-and-conditions','Terms governing use of the MyPro website.','Website information is provided for general business purposes and does not constitute a binding proposal. Product availability and solution details are subject to confirmation. These demonstration terms must be reviewed by legal counsel before production launch.']] as $x)$this->add('page',...$x); foreach([['How does an engagement begin?','We begin with a consultation to understand your business objectives, environment, constraints, and priorities.'],['Can MyPro support an existing IT environment?','Yes. The portfolio includes technical support, network administration, helpdesk, preventive maintenance, and technical resource deployment.'],['Which customer segments does MyPro serve?','MyPro serves large enterprises, small and medium businesses, small office/home office environments, and the retail market.'],['Can MyPro supply both hardware and software?','Yes. Portfolio capabilities include computing devices, servers, storage, peripherals, security products, and business software licensing.']] as $x)$this->add('faq',$x[0],str($x[0])->slug(),'', $x[1]); foreach(['Huawei','Sophos','Secureworks','Panduit','ZingHR','Cisco','Lenovo','Dell EMC','Microsoft','Adobe','HPE','Kaspersky'] as $p)$this->add('partner',$p,str($p)->slug(),'Portfolio product line or solution partner.'); foreach([['Sample: Multi-site Network Modernization','sample-network-modernization','Demonstration scenario for consolidating connectivity and structured cabling across growing locations.'],['Sample: Layered Endpoint Security','sample-endpoint-security','Demonstration scenario for improving endpoint visibility and protection with managed support.'],['Sample: Resilient Server Environment','sample-server-environment','Demonstration scenario for modernizing compute, storage, backup power, and administration.']] as $x)$this->add('project',$x[0],$x[1],$x[2],'This is sample content only. It does not describe a verified MyPro customer or completed project.'); }}
